parameters.text:
=Classify this employee feedback.

Department: {{ $json['Department'] }}

Feedback:
<<<
{{ $json['Your Feedback'] }}
>>>

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "enum": [
        "Compensation & Benefits",
        "Staff Welfare & Wellbeing",
        "Work-Life Balance",
        "Management & Leadership",
        "Career Growth & Training",
        "Workplace & Facilities",
        "Tools & Resources",
        "Culture & Inclusion",
        "Communication",
        "Safety & Compliance",
        "Other"
      ]
    },
    "sentiment": {
      "type": "string",
      "enum": [
        "Positive",
        "Neutral",
        "Negative",
        "Mixed"
      ]
    },
    "sentiment_score": {
      "type": "number"
    },
    "urgency": {
      "type": "string",
      "enum": [
        "Low",
        "Medium",
        "High",
        "Critical"
      ]
    },
    "request": {
      "type": "string"
    },
    "summary": {
      "type": "string"
    }
  },
  "required": [
    "category",
    "sentiment",
    "sentiment_score",
    "urgency",
    "request",
    "summary"
  ]
}

parameters.jsCode:
const rows = $input.all().map(i => i.json).filter(r => r['Feedback'] && String(r['Feedback']).trim());

const stats = {
  total: rows.length,
  avgScore: 0,
  sentiment: { Positive: 0, Neutral: 0, Negative: 0, Mixed: 0 },
  urgency: { Low: 0, Medium: 0, High: 0, Critical: 0 },
  categories: {},
  departments: {},
  requests: {}
};

let scoreSum = 0, scoreN = 0;

for (const r of rows) {
  const cat = r['Category'] || 'Other';
  const sent = r['Sentiment'] || 'Neutral';
  const dep = r['Department'] || 'Unspecified';
  const urg = r['Urgency'] || 'Low';
  const score = parseFloat(r['Sentiment Score']);
  const req = String(r['Request'] || '').trim();

  stats.sentiment[sent] = (stats.sentiment[sent] || 0) + 1;
  stats.urgency[urg] = (stats.urgency[urg] || 0) + 1;

  if (!stats.categories[cat]) stats.categories[cat] = { count: 0, Positive: 0, Neutral: 0, Negative: 0, Mixed: 0, scoreSum: 0 };
  const c = stats.categories[cat];
  c.count++;
  c[sent] = (c[sent] || 0) + 1;
  if (!isNaN(score)) c.scoreSum += score;

  if (!stats.departments[dep]) stats.departments[dep] = { count: 0, Negative: 0, scoreSum: 0 };
  const d = stats.departments[dep];
  d.count++;
  if (sent === 'Negative') d.Negative++;
  if (!isNaN(score)) d.scoreSum += score;

  if (!isNaN(score)) { scoreSum += score; scoreN++; }

  if (req && req.toLowerCase() !== 'none') {
    const key = req.replace(/\s+/g, ' ');
    stats.requests[key] = (stats.requests[key] || 0) + 1;
  }
}

stats.avgScore = scoreN ? +(scoreSum / scoreN).toFixed(2) : 0;
for (const k of Object.keys(stats.categories)) {
  const c = stats.categories[k];
  c.avgScore = c.count ? +(c.scoreSum / c.count).toFixed(2) : 0;
  delete c.scoreSum;
}
for (const k of Object.keys(stats.departments)) {
  const d = stats.departments[k];
  d.avgScore = d.count ? +(d.scoreSum / d.count).toFixed(2) : 0;
  delete d.scoreSum;
}

const entries = rows.slice(-150).map(r =>
  `${r['Timestamp'] || ''} | ${r['Department'] || ''} | ${r['Category'] || ''} | ${r['Sentiment'] || ''} | ${r['Urgency'] || ''} | ${String(r['Feedback']).slice(0, 300).replace(/\s+/g, ' ')}`
);

return [{ json: { stats, entries } }];

parameters.text:
=Prepare the HR briefing from the complete feedback sheet.

AGGREGATED STATISTICS (accurate, do not recalculate):
{{ JSON.stringify($json.stats, null, 2) }}

FEEDBACK ENTRIES (Timestamp | Department | Category | Sentiment | Urgency | Feedback), oldest to newest, the LAST line is the newest feedback:
{{ $json.entries.join('\n') }}

parameters.jsCode:
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const a = $json.output || {};
const s = $('Aggregate Sheet Data').first().json.stats;
const latest = $('Assemble Row').first().json;

const COL = { Positive:'#2e7d32', Neutral:'#90a4ae', Mixed:'#f9a825', Negative:'#c62828' };
const URG = { Low:'#2e7d32', Medium:'#f9a825', High:'#ef6c00', Critical:'#c62828' };
const MOOD = { 'Positive':'#2e7d32', 'Neutral':'#546e7a', 'Concerned':'#ef6c00', 'At Risk':'#c62828' };
const pill = (t, c) => `<span style="display:inline-block;background:${c};color:#fff;padding:3px 10px;border-radius:12px;font-size:11px;font-weight:bold;">${esc(t)}</span>`;
const scoreColor = v => v > 0.25 ? COL.Positive : (v < -0.25 ? COL.Negative : COL.Mixed);
const scoreLabel = v => v > 0.25 ? 'Positive' : (v < -0.25 ? 'Negative' : 'Mixed');
const pct = (n, t) => t ? Math.round(n / t * 100) : 0;

const h3 = (t, color) => `<h3 style="margin:30px 0 12px;font-size:16px;color:${color || '#1a237e'};border-bottom:2px solid #e8eaf6;padding-bottom:6px;">${t}</h3>`;
const ul = arr => (arr && arr.length) ? `<ul style="margin:0;padding-left:20px;">${arr.map(i => `<li style="margin-bottom:6px;">${esc(i)}</li>`).join('')}</ul>` : '<p style="margin:0;color:#888;">None identified.</p>';

const kpi = (label, value, color, sub) => `
<td style="width:25%;padding:4px;">
  <div style="background:#fff;border:1px solid #e0e0e0;border-top:4px solid ${color};border-radius:6px;padding:12px 8px;text-align:center;">
    <div style="font-size:24px;font-weight:bold;color:${color};">${value}</div>
    <div style="font-size:11px;color:#666;text-transform:uppercase;letter-spacing:.5px;margin-top:2px;">${label}</div>
    ${sub ? `<div style="font-size:11px;color:#999;margin-top:2px;">${sub}</div>` : ''}
  </div>
</td>`;

const total = s.total;
const negPct = pct(s.sentiment.Negative, total);
const urgent = (s.urgency.High || 0) + (s.urgency.Critical || 0);

// Sentiment distribution bar
const sentBar = ['Positive','Neutral','Mixed','Negative'].map(k => {
  const n = s.sentiment[k] || 0;
  return n ? `<td style="width:${pct(n,total)}%;background:${COL[k]};height:18px;font-size:1px;line-height:1px;">&nbsp;</td>` : '';
}).join('');
const sentLegend = ['Positive','Neutral','Mixed','Negative'].map(k =>
  `<span style="display:inline-block;margin-right:14px;font-size:12px;"><span style="display:inline-block;width:10px;height:10px;background:${COL[k]};border-radius:2px;margin-right:4px;"></span>${k}: <b>${s.sentiment[k] || 0}</b> (${pct(s.sentiment[k] || 0, total)}%)</span>`
).join('');

// Categories
const cats = Object.entries(s.categories).sort((x, y) => y[1].count - x[1].count);
const maxCat = cats.length ? cats[0][1].count : 1;
const insightMap = {};
(a.category_insights || []).forEach(i => { insightMap[i.category] = i.insight; });

const catRows = cats.map(([name, c]) => {
  const seg = k => c[k] > 0 ? `<td style="width:${(c[k] / c.count * 100).toFixed(1)}%;background:${COL[k]};height:14px;font-size:1px;line-height:1px;">&nbsp;</td>` : '';
  const w = Math.max(10, Math.round(c.count / maxCat * 100));
  return `
<tr>
  <td style="padding:10px 8px;border-bottom:1px solid #eee;vertical-align:top;width:34%;">
    <b style="font-size:13px;">${esc(name)}</b><br>
    <span style="font-size:11px;color:#777;">avg score ${c.avgScore} · ${pct(c.count, total)}% of feedback</span>
  </td>
  <td style="padding:10px 8px;border-bottom:1px solid #eee;vertical-align:top;">
    <table role="presentation" width="${w}%" cellpadding="0" cellspacing="0" style="border-radius:7px;overflow:hidden;"><tr>${seg('Positive')}${seg('Neutral')}${seg('Mixed')}${seg('Negative')}</tr></table>
    <div style="font-size:11px;color:#555;margin-top:4px;"><b>${c.count}</b> staff · <span style="color:${COL.Positive}">${c.Positive} pos</span> · <span style="color:${COL.Neutral}">${c.Neutral} neu</span> · <span style="color:#b58900">${c.Mixed} mixed</span> · <span style="color:${COL.Negative}">${c.Negative} neg</span></div>
    ${insightMap[name] ? `<div style="font-size:12px;color:#444;margin-top:5px;font-style:italic;">${esc(insightMap[name])}</div>` : ''}
  </td>
</tr>`;
}).join('');

// Requests
const reqs = Object.entries(s.requests).sort((x, y) => y[1] - x[1]).slice(0, 10);
const reqRows = reqs.length ? reqs.map(([name, n]) => `
<tr><td style="padding:7px 8px;border-bottom:1px solid #eee;font-size:13px;">${esc(name)}</td>
<td style="padding:7px 8px;border-bottom:1px solid #eee;text-align:right;">${pill(n + (n === 1 ? ' staff' : ' staff'), '#5e35b1')}</td></tr>`).join('')
  : '<tr><td style="padding:8px;color:#888;font-size:13px;">No specific requests recorded yet.</td></tr>';

// Departments
const deps = Object.entries(s.departments).sort((x, y) => y[1].count - x[1].count);
const depRows = deps.map(([name, d]) => `
<tr>
  <td style="padding:7px 8px;border-bottom:1px solid #eee;font-size:13px;">${esc(name)}</td>
  <td style="padding:7px 8px;border-bottom:1px solid #eee;text-align:center;font-size:13px;">${d.count}</td>
  <td style="padding:7px 8px;border-bottom:1px solid #eee;text-align:center;font-size:13px;color:${d.Negative ? COL.Negative : '#555'};">${d.Negative}</td>
  <td style="padding:7px 8px;border-bottom:1px solid #eee;text-align:center;">${pill(d.avgScore, scoreColor(d.avgScore))}</td>
</tr>`).join('');

// Priorities
const prioCards = (a.top_priorities || []).map((p, i) => `
<div style="border-left:5px solid ${i === 0 ? '#c62828' : (i === 1 ? '#ef6c00' : '#1a237e')};background:#fafafa;border-radius:4px;padding:12px 14px;margin-bottom:10px;">
  <div style="font-weight:bold;font-size:14px;">${i + 1}. ${esc(p.title)}</div>
  <div style="font-size:13px;color:#555;margin:4px 0;">${esc(p.why)}</div>
  <div style="font-size:13px;"><b style="color:#1a237e;">Recommended action:</b> ${esc(p.recommended_action)}</div>
</div>`).join('');

const mood = a.overall_mood || 'Neutral';
const urgColor = URG[latest.Urgency] || '#555';
const sentColor = COL[latest.Sentiment] || '#555';

const html = `
<div style="background:#eef1f7;padding:20px 10px;font-family:Arial,Helvetica,sans-serif;color:#222;line-height:1.5;">
<div style="max-width:720px;margin:auto;background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,.08);">

  <div style="background:linear-gradient(135deg,#1a237e,#5e35b1);color:#fff;padding:26px 28px;">
    <div style="font-size:12px;letter-spacing:1.5px;opacity:.8;">HR INSIGHTS</div>
    <h1 style="margin:4px 0 6px;font-size:24px;">Employee Feedback Report</h1>
    <div style="font-size:13px;opacity:.9;">Updated automatically after new feedback · ${esc(new Date().toUTCString())}</div>
    <div style="margin-top:12px;">Overall mood: ${pill(mood, MOOD[mood] || '#546e7a')}</div>
  </div>

  <div style="padding:24px 28px;">

    <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
      ${kpi('Total feedback', total, '#1a237e')}
      ${kpi('Avg sentiment', s.avgScore, scoreColor(s.avgScore), scoreLabel(s.avgScore))}
      ${kpi('Negative', negPct + '%', COL.Negative, s.sentiment.Negative + ' of ' + total)}
      ${kpi('High / Critical', urgent, urgent ? '#ef6c00' : COL.Positive, 'need attention')}
    </tr></table>

    <div style="background:#f3f0fb;border-radius:8px;padding:14px 16px;margin-top:18px;font-size:14px;">
      <b style="color:#1a237e;">Executive summary</b><br>${esc(a.executive_summary)}
    </div>

    <div style="border:2px solid ${urgColor};border-radius:8px;padding:14px 16px;margin-top:18px;">
      <div style="font-size:12px;font-weight:bold;color:${urgColor};letter-spacing:1px;">🆕 LATEST FEEDBACK RECEIVED</div>
      <div style="margin:8px 0;">${pill(latest.Category, '#1a237e')} ${pill(latest.Sentiment, sentColor)} ${pill('Urgency: ' + latest.Urgency, urgColor)}</div>
      <div style="font-size:13px;color:#555;">${esc(latest.Department)} · ${esc(latest['Employee Name'])}</div>
      <div style="font-size:14px;margin-top:6px;"><b>${esc(latest.Summary)}</b></div>
      <blockquote style="margin:10px 0 0;padding:8px 12px;background:#f5f5f5;border-left:4px solid ${sentColor};font-size:13px;white-space:pre-wrap;">${esc(latest.Feedback)}</blockquote>
      <div style="font-size:13px;color:#444;margin-top:10px;">${esc(a.latest_feedback_comment)}</div>
    </div>

    ${h3('Sentiment overview')}
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-radius:9px;overflow:hidden;"><tr>${sentBar}</tr></table>
    <div style="margin-top:8px;">${sentLegend}</div>

    ${h3('Feedback by category')}
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0">${catRows}</table>

    ${h3('What staff are requesting', '#5e35b1')}
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0">${reqRows}</table>

    ${h3('Top priorities for HR', '#c62828')}
    ${prioCards || '<p style="color:#888;">No priorities identified.</p>'}

    ${h3('Emerging risks', '#ef6c00')}
    ${ul(a.emerging_risks)}

    ${h3('Positive highlights', '#2e7d32')}
    ${ul(a.positive_highlights)}

    ${h3('By department')}
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
      <tr style="background:#e8eaf6;font-size:12px;color:#1a237e;">
        <th style="padding:8px;text-align:left;">Department</th><th style="padding:8px;">Responses</th><th style="padding:8px;">Negative</th><th style="padding:8px;">Avg score</th>
      </tr>${depRows}
    </table>

    <p style="margin-top:30px;font-size:11px;color:#999;border-top:1px solid #eee;padding-top:12px;">
      This report is generated automatically from the Employee Feedback Google Sheet using Grok. All statistics reflect every response currently in the sheet. Confidential: for HR use only.
    </p>
  </div>
</div>
</div>`;

const prefix = latest.Urgency === 'Critical' ? '🚨 [CRITICAL] ' : (latest.Urgency === 'High' ? '⚠️ [HIGH] ' : '📊 ');
const subject = `${prefix}Employee Feedback Report: ${total} responses | New: ${latest.Category} (${latest.Sentiment})`;

return [{ json: { subject, html } }];
